/workspace/.venv/bin/python -c "
import glob, os
# map inode->pid from /proc/*/fd
inodes={}
for fd in glob.glob('/proc/[0-9]*/fd/*'):
    try:
        t=os.readlink(fd)
        if t.startswith('socket:['): inodes[t[8:-1]]=fd.split('/')[2]
    except Exception: pass
# find sockets bound to 18011 (0x468B)
for f in ('/proc/net/tcp','/proc/net/tcp6'):
    try: lines=open(f).read().splitlines()[1:]
    except FileNotFoundError: continue
    for ln in lines:
        p=ln.split()
        local=p[1]; st=p[3]; inode=p[9]
        if int(local.split(':')[1],16)==18011:
            pid=inodes.get(inode,'?')
            print(f'port=18011 state={st} inode={inode} pid={pid}')
            if pid!='?':
                print('  cmdline:', open(f'/proc/{pid}/cmdline').read().replace(chr(0),' ')[:200])
"

